-- OpenXE API permission seed.
--
-- The OpenXE API requires two things to authorize an account:
--   1. Rows in api_permission describing the available permission keys
--      (needed by the admin UI for toggling permissions per account).
--   2. A JSON array on api_account.permissions listing the keys the
--      account is allowed to use at runtime.
--
-- Fresh OpenXE deploys do NOT pre-populate either of these, so after
-- a first install the API always returns 401. This seed script fixes
-- both for the default API account (id = 1).
--
-- Keys captured from a working production install: 217 total.
-- Run after initial deploy:
--   docker compose exec mysql mysql -uroot -p<pw> ${MYSQL_DATABASE:-openxe} < database/seed-api-permissions.sql

-- 1. Populate api_permission so the permission editor UI can render.
--    INSERT IGNORE so re-running is a no-op once keys already exist.

-- 2. Grant all permissions to the default API account.
--    Override whatever was set before (NULL or a narrower list).
UPDATE api_account SET permissions = '["communicate_with_shop", "create_address", "create_address_type", "create_article_category", "create_country", "create_crm_document", "create_delivery_address", "create_file", "create_group", "create_payment_method", "create_property", "create_property_value", "create_resubmission", "create_scanned_document", "create_shipping_method", "create_subscription", "create_subscription_group", "create_tax_rate", "create_tracking_number", "delete_crm_document", "delete_delivery_address", "delete_invoice", "delete_property", "delete_property_value", "delete_subscription", "edit_address", "edit_address_type", "edit_article", "edit_article_category", "edit_country", "edit_crm_document", "edit_delivery_address", "edit_group", "edit_payment_method", "edit_property", "edit_property_value", "edit_resubmission", "edit_shipping_method", "edit_subscription", "edit_subscription_group", "edit_tax_rate", "edit_tracking_number", "handle_assets", "handle_navision", "handle_opentrans", "import_csv_file", "list_address_types", "list_addresses", "list_article_categories", "list_articles", "list_countries", "list_credit_memos", "list_crm_documents", "list_delivery_addresses", "list_delivery_notes", "list_documents", "list_files", "list_groups", "list_invoices", "list_orders", "list_payment_methods", "list_property", "list_property_value", "list_quotes", "list_resubmissions", "list_scanned_documents", "list_shipping_methods", "list_subscription_groups", "list_subscriptions", "list_tax_rates", "list_tracking_numbers", "mobile_app_communication", "standard_accountcreate", "standard_accountedit", "standard_accountlist", "standard_accountlogin", "standard_adresseaboartikelcreate", "standard_adresseaboartikeledit", "standard_adresseaboartikelget", "standard_adresseaboartikellist", "standard_adresseabogruppecreate", "standard_adresseabogruppeedit", "standard_adresseabogruppeget", "standard_adresseabogruppelist", "standard_adresseaccountsget", "standard_adressecr